<section class="mx-auto max-w-6xl px-4 py-12 sm:px-6 lg:px-8"><h1 class="text-4xl font-semibold">Checkout</h1><div class="mt-8 grid gap-8 lg:grid-cols-[1fr_22rem]"><div class="grid gap-6"><flux:card><flux:heading size="lg">1. Contact and shipping address</flux:heading><form wire:submit="saveAddress" class="mt-5 grid gap-4 sm:grid-cols-2"><flux:input class="sm:col-span-2" wire:model="email" type="email" label="Email" /><flux:input wire:model="shipping.first_name" label="First name" /><flux:input wire:model="shipping.last_name" label="Last name" /><flux:input class="sm:col-span-2" wire:model="shipping.address1" label="Address" /><flux:input wire:model="shipping.city" label="City" /><flux:input wire:model="shipping.postal_code" label="Postal code" /><flux:input wire:model="shipping.country" label="Country code" maxlength="2" /><flux:input wire:model="shipping.phone" label="Phone (optional)" /><flux:button class="sm:col-span-2" type="submit" variant="primary">Continue to shipping</flux:button></form></flux:card>@if ($checkout->status->value !== 'started')<flux:card><flux:heading size="lg">2. Shipping method</flux:heading><fieldset class="mt-5 grid gap-3"><legend class="sr-only">Choose a shipping method</legend>@forelse ($rates as $rate)<label wire:key="rate-{{ $rate->id }}" class="flex cursor-pointer justify-between rounded-xl border border-zinc-300 p-4 dark:border-zinc-700"><span>{{ $rate->name }}</span><input type="radio" wire:model="shippingRateId" value="{{ $rate->id }}"></label>@empty<p>No shipping required or no rates available.</p>@endforelse</fieldset><flux:button wire:click="selectShipping" class="mt-4" variant="primary">Continue to payment</flux:button></flux:card>@endif@if (in_array($checkout->status->value, ['shipping_selected', 'payment_selected']))<flux:card><flux:heading size="lg">3. Payment</flux:heading><fieldset class="mt-5 grid gap-3"><legend class="sr-only">Payment method</legend>@foreach (['credit_card' => 'Credit card', 'paypal' => 'PayPal', 'bank_transfer' => 'Bank transfer'] as $value => $label)<label class="flex cursor-pointer gap-3 rounded-xl border border-zinc-300 p-4 dark:border-zinc-700"><input type="radio" wire:model.live="paymentMethod" value="{{ $value }}"><span>{{ $label }}</span></label>@endforeach</fieldset>@if ($paymentMethod === 'credit_card')<flux:input class="mt-4" wire:model="cardNumber" label="Card number" autocomplete="cc-number" />@endif@if ($checkout->status->value === 'shipping_selected')<flux:button wire:click="selectPayment" class="mt-4" variant="primary">Review payment</flux:button>@else<flux:button wire:click="pay" class="mt-4 w-full" variant="primary">Pay now</flux:button>@endif</flux:card>@endif</div><aside class="h-fit rounded-2xl bg-zinc-100 p-6 dark:bg-zinc-900"><h2 class="text-xl font-semibold">Order summary</h2><div class="mt-5 grid gap-3">@foreach ($checkout->cart->lines as $line)<div wire:key="summary-line-{{ $line->id }}" class="flex justify-between gap-3 text-sm"><span>{{ $line->quantity }} × {{ $line->variant->product->title }}</span><x-storefront.price :amount="$line->line_total_amount" :currency="$checkout->cart->currency" /></div>@endforeach</div><div class="mt-5 border-t border-zinc-300 pt-5 dark:border-zinc-700"><div class="flex justify-between font-semibold"><span>Total</span><x-storefront.price :amount="$checkout->totals_json['total'] ?? $checkout->cart->lines->sum('line_total_amount')" :currency="$checkout->cart->currency" /></div></div><form wire:submit="applyDiscount" class="mt-5 grid gap-2"><flux:input wire:model="discountCode" label="Discount code" /><flux:button type="submit">Apply discount</flux:button></form></aside></div></section>
